import XCTest
@testable import WeddingCore

final class CloudTests:XCTestCase {
    func state(_ db:WeddingArchive) throws -> CloudState {CloudState(accountID:"owner",weddingID:UUID().uuidString,ownerID:"owner",records:try CloudProjection.records(db),ready:true)}
    func testLegacyBackupWithoutCloudStillDecodes() throws {var db = WeddingArchive();db.guests = [Guest(name:"Anna")];let data = try JSONEncoder().encode(db);XCTAssertNil(try JSONDecoder().decode(WeddingArchive.self,from:data).cloud)}
    func testFullProjectionRoundTripIncludingSeparatePayments() throws {var db = WeddingArchive();let v = Vendor(name:"Fiori");let t = WeddingTable(name:"Rosa");db.vendors = [v];db.tables = [t];db.guests = [Guest(name:"Anna",tableID:t.id)];db.tasks = [WeddingTask(title:"Prenota",vendorID:v.id)];db.expenses = [Expense(title:"Fiori",planned:50000,payments:[Payment(amount:10000)],vendorID:v.id)];db.schedule = [ScheduleEntry(title:"Prima"),ScheduleEntry(title:"Dopo")];db.notes = [WeddingNote(title:"Nota",kind:.guest,linkedID:db.guests[0].id)];var result = try CloudProjection.materialize(state(db),reminders:true);result.cloud = nil;db.settings.reminders = true;XCTAssertEqual(result,db)}
    func testNotificationPreferenceNeverShared() throws {var db = WeddingArchive();db.settings.reminders = true;let records = try CloudProjection.records(db);XCTAssertNil(records["settings"]?.fields["reminders"]);XCTAssertFalse(try CloudProjection.materialize(state(db),reminders:false).settings.reminders)}
    func testCurrencyCannotChangeWhileSharing() throws {let base = WeddingArchive();var edited = base;edited.settings.currency = "USD";var state = try state(base);XCTAssertThrowsError(try state.capture(before:base,after:edited))}
    func testJoiningNeverUploadsOrShowsUnrelatedPersonalArchive() throws {var local = WeddingArchive();local.guests = [Guest(name:"Privato")];local.settings.reminders = true;let s = CloudState(accountID:"partner",weddingID:UUID().uuidString,ownerID:"owner",ready:true);let attached = try CloudProjection.attach(s,to:local,uploadLocal:false);XCTAssertTrue(attached.guests.isEmpty);XCTAssertTrue(attached.cloud!.pending.isEmpty);XCTAssertTrue(attached.cloud!.awaitingInitialData);XCTAssertTrue(attached.settings.reminders);XCTAssertEqual(local.guests.count,1)}
    func testPaymentOnDeletedExpenseIsRecoverableInViewAndBackup() throws {var db = WeddingArchive();db.expenses = [Expense(title:"Fiori",planned:50000,payments:[Payment(amount:10000)])];var s = try state(db);let key = "expense_" + db.expenses[0].id.uuidString;s.records[key]?.deleted = true;let visible = try CloudProjection.materialize(s,reminders:false);XCTAssertEqual(visible.paid,10000);XCTAssertEqual(s.conflicts.count,1);XCTAssertTrue(s.conflicts[0].recovery);s.resolve(key,keepLocal:true);XCTAssertEqual(s.pending.first?.desired?.kind,"expense");XCTAssertFalse(s.conflicts.contains {$0.recovery})}
    func testConfirmDeletingExpenseAlsoTombstonesOrphanPayments() throws {var db = WeddingArchive();db.expenses = [Expense(title:"Fiori",payments:[Payment(amount:10000)])];var s = try state(db);let key = "expense_" + db.expenses[0].id.uuidString;s.records[key]?.deleted = true;s.resolve(key,keepLocal:false);let visible = try CloudProjection.materialize(s,reminders:false);XCTAssertEqual(visible.paid,0);XCTAssertTrue(visible.expenses.isEmpty);XCTAssertTrue(s.pending.allSatisfy {$0.desired == nil})}
    func testDifferentRowsMergeWithoutLoss() throws {var a = WeddingArchive();a.guests = [Guest(name:"Anna"),Guest(name:"Luca")];var s = try state(a);var local = a;local.guests[0].rsvp = .confirmed;try s.capture(before:a,after:local);var remote = a;remote.guests[1].rsvp = .declined;s.records = try CloudProjection.records(remote);let result = try CloudProjection.materialize(s,reminders:false);XCTAssertEqual(result.guests.first {$0.name == "Anna"}?.rsvp,.confirmed);XCTAssertEqual(result.guests.first {$0.name == "Luca"}?.rsvp,.declined);XCTAssertTrue(s.conflicts.isEmpty)}
    func testDifferentFieldsInSameGuestMergeWithoutConflict() throws {var a = WeddingArchive();a.guests = [Guest(name:"Anna")];var s = try state(a);var local = a;local.guests[0].rsvp = .confirmed;try s.capture(before:a,after:local);var remote = a;remote.guests[0].diet = "Vegetariano";s.records = try CloudProjection.records(remote);XCTAssertTrue(s.conflicts.isEmpty);let result = try CloudProjection.materialize(s,reminders:false);XCTAssertEqual(result.guests[0].rsvp,.confirmed);XCTAssertEqual(result.guests[0].diet,"Vegetariano")}
    func testSameFieldConflictPreservesBothVersionsUntilChoice() throws {var a = WeddingArchive();a.guests = [Guest(name:"Anna")];var s = try state(a);var local = a;local.guests[0].diet = "Locale";try s.capture(before:a,after:local);var remote = a;remote.guests[0].diet = "Remoto";s.records = try CloudProjection.records(remote);XCTAssertEqual(s.conflicts.count,1);XCTAssertEqual(s.conflicts[0].fields,["diet"]);XCTAssertEqual(try CloudProjection.materialize(s,reminders:false).guests[0].diet,"Locale");s.resolve(s.pending[0].key,keepLocal:false);XCTAssertEqual(try CloudProjection.materialize(s,reminders:false).guests[0].diet,"Remoto")}
    func testKeepLocalRebasesOnlyIntendedFields() throws {let base = CloudRecord(id:"guest_x",kind:"guest",fields:["name":"old","diet":"old"]);let local = CloudRecord(id:"guest_x",kind:"guest",fields:["name":"mine","diet":"old"]);let remote = CloudRecord(id:"guest_x",kind:"guest",fields:["name":"other","diet":"new"]);var s = CloudState(accountID:"a",weddingID:"w",ownerID:"a",records:[remote.id:remote],pending:[CloudMutation(key:base.id,base:base,desired:local,keys:["name"])]);s.resolve(base.id,keepLocal:true);let result = CloudMerge.applying(s.pending[0],to:remote);XCTAssertEqual(result.fields["name"],"mine");XCTAssertEqual(result.fields["diet"],"new");XCTAssertTrue(s.conflicts.isEmpty)}
    func testDeleteVersusEditRequiresChoice() {let base = CloudRecord(id:"task_x",kind:"task",fields:["title":"a"]);var remote = base;remote.fields["title"] = "b";let delete = CloudMutation(key:base.id,base:base,keys:["title"]);XCTAssertNotNil(CloudMerge.conflict(delete,remote:remote));var tombstone = base;tombstone.deleted = true;var local = base;local.fields["title"] = "c";XCTAssertNotNil(CloudMerge.conflict(CloudMutation(key:base.id,base:base,desired:local,keys:["title"]),remote:tombstone))}
    func testRepeatedOfflineChangesCoalesceAndRevertRemovesQueue() throws {var a = WeddingArchive();a.tasks = [WeddingTask(title:"A")];var s = try state(a);var b = a;b.tasks[0].title = "B";try s.capture(before:a,after:b);var c = b;c.tasks[0].title = "C";try s.capture(before:b,after:c);XCTAssertEqual(s.pending.count,1);try s.capture(before:c,after:a);XCTAssertTrue(s.pending.isEmpty)}
    func testEditWhileWriteInFlightSurvivesAcknowledgement() throws {var a = WeddingArchive();a.tasks = [WeddingTask(title:"A")];var s = try state(a);var b = a;b.tasks[0].title = "B";try s.capture(before:a,after:b);let sent = s.pending[0];var c = b;c.tasks[0].title = "C";try s.capture(before:b,after:c);let committed = CloudMerge.applying(sent,to:s.records[sent.key]);s.acknowledge(sent,committed:committed);XCTAssertEqual(s.pending.count,1);XCTAssertTrue(s.conflicts.isEmpty);XCTAssertEqual(try CloudProjection.materialize(s,reminders:false).tasks[0].title,"C")}
    func testRemoteFieldIsNotTurnedIntoUnintendedLocalEdit() throws {var a = WeddingArchive();a.guests = [Guest(name:"Anna")];var s = try state(a);var b = a;b.guests[0].rsvp = .confirmed;try s.capture(before:a,after:b);var remote = a;remote.guests[0].diet = "Remoto 1";s.records = try CloudProjection.records(remote);let visible = try CloudProjection.materialize(s,reminders:false);var edited = visible;edited.guests[0].notes = "Nota locale";try s.capture(before:visible,after:edited);remote.guests[0].diet = "Remoto 2";s.records = try CloudProjection.records(remote);XCTAssertTrue(s.conflicts.isEmpty);XCTAssertEqual(try CloudProjection.materialize(s,reminders:false).guests[0].diet,"Remoto 2")}
    func testTwoConcurrentPaymentsRemainDistinct() throws {var a = WeddingArchive();a.expenses = [Expense(title:"Fiori",planned:50000)];var s = try state(a);var local = a;local.expenses[0].payments.append(Payment(amount:10000));try s.capture(before:a,after:local);var remote = a;remote.expenses[0].payments.append(Payment(amount:20000));s.records = try CloudProjection.records(remote);let combined = try CloudProjection.materialize(s,reminders:false);XCTAssertEqual(combined.expenses[0].payments.count,2);XCTAssertEqual(combined.paid,30000);XCTAssertTrue(s.conflicts.isEmpty)}
    func testTombstoneDetachesReferencesButKeepsGuests() throws {var a = WeddingArchive();let t = WeddingTable(name:"Rosa");a.tables = [t];a.guests = [Guest(name:"Anna",tableID:t.id)];var s = try state(a);let key = "table_" + t.id.uuidString;s.records[key]?.deleted = true;let result = try CloudProjection.materialize(s,reminders:false);XCTAssertNil(result.guests[0].tableID);XCTAssertEqual(result.guests.count,1);XCTAssertNotNil(s.records["guest_" + a.guests[0].id.uuidString]?.fields["tableID"])}
    func testQueuePersistsAtomicallyWithLocalChanges() throws {let r = WeddingRepository(directory:FileManager.default.temporaryDirectory.appendingPathComponent(UUID().uuidString));defer {try? FileManager.default.removeItem(at:r.directory)};try r.update {$0.cloud = try state($0)};try r.update {archive in let old = archive;archive.tasks = [WeddingTask(title:"Offline")];var s = archive.cloud!;try s.capture(before:old,after:archive);archive.cloud = s};let reloaded = try r.read();XCTAssertEqual(reloaded.tasks.count,1);XCTAssertEqual(reloaded.cloud?.pending.count,1)}
}
